package com.picog2.pulsesaber;
import android.opengl.GLSurfaceView;import android.opengl.GLES20;import android.opengl.Matrix;import android.os.SystemClock;import android.view.MotionEvent;import java.nio.*;import java.util.*;import org.json.*;import javax.microedition.khronos.egl.EGLConfig;import javax.microedition.khronos.opengles.GL10;

/** GLES2 scene: original arena plus two converted CC0 external meshes. No PICO runtime simulation. */
final class ArenaView extends GLSurfaceView implements GLSurfaceView.Renderer {
 final MainActivity app;int program,posLoc,rgbLoc,mvpLoc,tintLoc,width=1280,height=720;final float[] projection=new float[16],view=new float[16],vp=new float[16],model=new float[16],mvp=new float[16],inverse=new float[16];Mesh cube,arrow,robot,boombox;RhythmGame game;float cursorX=.5f,cursorY=.5f,previousX,previousY,saberX=.4f,saberY=1.3f;boolean hasPrevious=false;long previousAt,lastFrame,lastHud;float effectTime;final ArrayList<Spark> sparks=new ArrayList<>();boolean resultSent=false;
 static final class Mesh{final FloatBuffer data;final int count;Mesh(float[] values){count=values.length/6;data=ByteBuffer.allocateDirect(values.length*4).order(ByteOrder.nativeOrder()).asFloatBuffer();data.put(values).position(0);}}
 static final class Spark{float x,y,z,vx,vy,vz,life;boolean bad;Spark(float x,float y,boolean b){this.x=x;this.y=y;z=-2.5f;vx=(float)(Math.random()-.5)*3;vy=(float)Math.random()*2;vz=(float)(Math.random()-.5)*2;life=.55f;bad=b;}}
 ArenaView(MainActivity a){super(a);app=a;setEGLContextClientVersion(2);setPreserveEGLContextOnPause(true);setRenderer(this);setRenderMode(RENDERMODE_CONTINUOUSLY);setFocusableInTouchMode(true);requestFocus();}
 void install(RhythmGame g){queueEvent(()->{game=g;hasPrevious=false;resultSent=false;sparks.clear();});}
 void endSong(){queueEvent(()->{if(game!=null){game.update(game.duration);game.finished=true;}});}
 void clearGame(){queueEvent(()->{game=null;hasPrevious=false;sparks.clear();});}
 void resetPointer(){queueEvent(()->hasPrevious=false);}
 int shader(int type,String source){int s=GLES20.glCreateShader(type);GLES20.glShaderSource(s,source);GLES20.glCompileShader(s);int[] ok=new int[1];GLES20.glGetShaderiv(s,GLES20.GL_COMPILE_STATUS,ok,0);if(ok[0]==0)throw new IllegalStateException(GLES20.glGetShaderInfoLog(s));return s;}
 @Override public void onSurfaceCreated(GL10 gl,EGLConfig config){program=GLES20.glCreateProgram();int vs=shader(GLES20.GL_VERTEX_SHADER,"uniform mat4 uMVP;attribute vec3 aPosition;attribute vec3 aColor;varying vec3 color;void main(){color=aColor;gl_Position=uMVP*vec4(aPosition,1.0);}"),fs=shader(GLES20.GL_FRAGMENT_SHADER,"precision mediump float;uniform vec3 uTint;varying vec3 color;void main(){gl_FragColor=vec4(color*uTint,1.0);}");GLES20.glAttachShader(program,vs);GLES20.glAttachShader(program,fs);GLES20.glLinkProgram(program);int[] ok=new int[1];GLES20.glGetProgramiv(program,GLES20.GL_LINK_STATUS,ok,0);if(ok[0]==0)throw new IllegalStateException(GLES20.glGetProgramInfoLog(program));GLES20.glDeleteShader(vs);GLES20.glDeleteShader(fs);posLoc=GLES20.glGetAttribLocation(program,"aPosition");rgbLoc=GLES20.glGetAttribLocation(program,"aColor");mvpLoc=GLES20.glGetUniformLocation(program,"uMVP");tintLoc=GLES20.glGetUniformLocation(program,"uTint");GLES20.glEnable(GLES20.GL_DEPTH_TEST);cube=makeCube();arrow=makeArrow();try{robot=load("robot");boombox=load("boombox");}catch(Exception e){app.runOnUiThread(()->android.widget.Toast.makeText(app,"Falha ao carregar decoração CC0; arena disponível.",android.widget.Toast.LENGTH_LONG).show());}}
 Mesh load(String name)throws Exception{JSONArray v=new JSONObject(MainActivity.read(app.getAssets().open(name+".json"))).getJSONArray("vertices");float[] data=new float[v.length()];for(int i=0;i<data.length;i++)data[i]=(float)v.getDouble(i);return new Mesh(data);}
 Mesh makeCube(){float[][] p={{-.5f,-.5f,.5f},{.5f,-.5f,.5f},{.5f,.5f,.5f},{-.5f,.5f,.5f},{-.5f,-.5f,-.5f},{.5f,-.5f,-.5f},{.5f,.5f,-.5f},{-.5f,.5f,-.5f}};int[][] faces={{0,1,2,3},{1,5,6,2},{5,4,7,6},{4,0,3,7},{3,2,6,7},{4,5,1,0}};float[] values=new float[36*6];int at=0;for(int f=0;f<6;f++){float shade=new float[]{1,.7f,.55f,.8f,.95f,.45f}[f];for(int j:new int[]{0,1,2,0,2,3}){float[] v=p[faces[f][j]];for(float x:v)values[at++]=x;values[at++]=shade;values[at++]=shade;values[at++]=shade;}}return new Mesh(values);}
 Mesh makeArrow(){float[] xy={0,.4f,-.35f,0,.35f,0,-.1f,0,-.1f,-.35f,.1f,-.35f,-.1f,0,.1f,-.35f,.1f,0};float[] data=new float[xy.length/2*6];int at=0;for(int i=0;i<xy.length;i+=2){data[at++]=xy[i];data[at++]=xy[i+1];data[at++]=0;data[at++]=1;data[at++]=1;data[at++]=1;}return new Mesh(data);}
 @Override public void onSurfaceChanged(GL10 gl,int w,int h){width=w;height=h;GLES20.glViewport(0,0,w,h);}
 void draw(Mesh mesh,float x,float y,float z,float sx,float sy,float sz,float angle,float r,float g,float b){if(mesh==null)return;Matrix.setIdentityM(model,0);Matrix.translateM(model,0,x,y,z);if(angle!=0)Matrix.rotateM(model,0,angle,0,0,1);Matrix.scaleM(model,0,sx,sy,sz);Matrix.multiplyMM(mvp,0,vp,0,model,0);GLES20.glUniformMatrix4fv(mvpLoc,1,false,mvp,0);GLES20.glUniform3f(tintLoc,r,g,b);mesh.data.position(0);GLES20.glVertexAttribPointer(posLoc,3,GLES20.GL_FLOAT,false,24,mesh.data);mesh.data.position(3);GLES20.glVertexAttribPointer(rgbLoc,3,GLES20.GL_FLOAT,false,24,mesh.data);GLES20.glEnableVertexAttribArray(posLoc);GLES20.glEnableVertexAttribArray(rgbLoc);GLES20.glDrawArrays(GLES20.GL_TRIANGLES,0,mesh.count);}
 void box(float x,float y,float z,float sx,float sy,float sz,float r,float g,float b){draw(cube,x,y,z,sx,sy,sz,0,r,g,b);}
 @Override public void onDrawFrame(GL10 gl){long now=SystemClock.elapsedRealtime();long budget=new int[]{33,22,16}[app.quality];long wait=budget-(now-lastFrame);if(wait>0)SystemClock.sleep(wait);now=SystemClock.elapsedRealtime();float dt=Math.min(.06f,(now-lastFrame)/1000f);lastFrame=now;GLES20.glClearColor(.027f,.055f,.09f,1);GLES20.glClear(GLES20.GL_COLOR_BUFFER_BIT|GLES20.GL_DEPTH_BUFFER_BIT);GLES20.glUseProgram(program);Matrix.perspectiveM(projection,0,65,width/(float)Math.max(height,1),.08f,65);if(game!=null)Matrix.setLookAtM(view,0,0,1.6f,0,0,1.6f,-10,0,1,0);else Matrix.setLookAtM(view,0,4,3.3f,6,-2,.6f,-7,0,1,0);Matrix.multiplyMM(vp,0,projection,0,view,0);Matrix.invertM(inverse,0,vp,0);
 box(0,-.16f,-10,9,.22f,29,.07f,.12f,.18f);box(0,-.025f,-10,3.1f,.025f,25,.09f,.17f,.21f);for(int side:new int[]{-1,1})box(side*1.6f,0,-10,.025f,.025f,25,.65f,1,.8f);for(float z=-2.5f;z>-26;z-=1.5f)box(0,-.01f,z,3.2f,.015f,.013f,.22f,.36f,.35f);box(0,.02f,-2.5f,3.2f,.03f,.04f,.8f,1,.9f);
 int arches=app.quality==0?4:7;for(int i=0;i<arches;i++){float z=-5-i*3.5f,r=i%2==0?.2f:.35f,b=i%2==0?.4f:.6f;box(-3.6f,2.5f,z,.04f,5,.06f,r,.4f,b);box(3.6f,2.5f,z,.04f,5,.06f,r,.4f,b);box(0,5,z,7.2f,.04f,.06f,r,.4f,b);}for(int i=0;i<20;i++){float x=(i<10?-1:1)*(2.2f+(i%10)*.18f);float h=app.reduced?.6f:.3f+(float)Math.abs(Math.sin(now*.003+i*.7))*.8f;box(x,h/2,-9,.08f,h,.1f,.3f,.6f,.55f);}draw(robot,2.5f,0,-5.7f,2.3f,2.3f,2.3f,0,1,1,1);box(-2.6f,.1f,-5.5f,1.5f,.2f,.85f,.1f,.2f,.25f);draw(boombox,-2.6f,.25f,-5.5f,1.3f,1.3f,1.3f,0,1,1,1);
 if(game!=null){float t=app.playing?app.time():game.time;if(app.playing){game.update(t);if(game.finished&&!resultSent){resultSent=true;app.complete(game.score,game.hits,game.total,game.bestCombo,game.accuracy(),game.rank());}}for(RhythmGame.Note n:game.notes){float delta=n.time-t;if(n.judged||delta>3.2||delta<-.35)continue;float x=RhythmGame.LANES[n.lane],y=RhythmGame.ROWS[n.row],z=-2.5f-delta*5;float r=n.bomb?1:n.lane==1?.66f:.71f,g=n.bomb?.55f:n.lane==1?.6f:1,b=n.bomb?.28f:n.lane==1?1:.86f;draw(cube,x,y,z,.43f,.43f,.24f,n.bomb?45:0,r,g,b);if(!n.bomb)draw(arrow,x,y,z+.126f,.4f,.4f,1,new int[]{0,180,90,-90}[n.dir],.07f,.17f,.18f);}box(saberX,saberY+.1f,-2.37f,.025f,.65f,.025f,.8f,1,.9f);box(saberX,saberY-.3f,-2.37f,.055f,.19f,.055f,.33f,.45f,.5f);if(now-lastHud>120){lastHud=now;String feedback=game.last;if(!feedback.isEmpty()){game.last="";app.lastFeedback=feedback;app.feedbackAt=now;}String label=now-app.feedbackAt<600?app.lastFeedback:"";app.updateHud(app.titles[app.song]+"   "+game.score+" PTS   "+game.combo+"×   "+(int)game.health+"%   "+label);}}
 for(int i=sparks.size()-1;i>=0;i--){Spark s=sparks.get(i);s.life-=dt;if(s.life<=0){sparks.remove(i);continue;}s.x+=s.vx*dt;s.y+=s.vy*dt;s.z+=s.vz*dt;s.vy-=2*dt;float scale=.06f*s.life/.55f;box(s.x,s.y,s.z,scale,scale,scale,s.bad?1:.7f,s.bad?.5f:1,s.bad?.2f:.85f);}
 }
 void performCut(float ax,float ay,float bx,float by,boolean force){if(game==null||!app.playing)return;int hit=game.cut(ax,ay,bx,by,app.time(),force);if(hit!=0){app.feedback(hit<0);if(!app.reduced){RhythmGame.Note n=game.lastHit;for(int i=0;i<(app.quality==0?4:10)&&sparks.size()<60;i++)sparks.add(new Spark(RhythmGame.LANES[n.lane],RhythmGame.ROWS[n.row],hit<0));}}}
 void aim(boolean force){float[] a={cursorX*2-1,1-cursorY*2,-1,1},b={cursorX*2-1,1-cursorY*2,1,1},near=new float[4],far=new float[4];Matrix.multiplyMV(near,0,inverse,0,a,0);Matrix.multiplyMV(far,0,inverse,0,b,0);for(int i=0;i<3;i++){near[i]/=near[3];far[i]/=far[3];}float fraction=(-2.5f-near[2])/(far[2]-near[2]);float x=near[0]+fraction*(far[0]-near[0]),y=near[1]+fraction*(far[1]-near[1]);long now=SystemClock.elapsedRealtime();if(Math.abs(x)>2.5||y<.25||y>3.4){hasPrevious=false;return;}saberX=x;saberY=y-.15f;if(hasPrevious&&now-previousAt<150)performCut(previousX,previousY,x,y,force);else if(force)performCut(x,y,x,y,true);previousX=x;previousY=y;hasPrevious=true;previousAt=now;}
 void move(float dx,float dy){queueEvent(()->{cursorX=Math.max(0,Math.min(1,cursorX+dx));cursorY=Math.max(0,Math.min(1,cursorY+dy));aim(false);});}
 void press(){queueEvent(()->aim(true));}
 void keyCut(int lane){queueEvent(()->{if(game==null)return;float t=app.time();RhythmGame.Note best=null;for(RhythmGame.Note n:game.notes)if(!n.judged&&n.lane==lane&&(best==null||Math.abs(n.time-t)<Math.abs(best.time-t)))best=n;if(best!=null)performCut(RhythmGame.LANES[lane],RhythmGame.ROWS[best.row],RhythmGame.LANES[lane],RhythmGame.ROWS[best.row],true);});}
 @Override public boolean onTouchEvent(MotionEvent e){if(!app.playing)return true;final float x=e.getX()/width,y=e.getY()/height;final int action=e.getActionMasked();queueEvent(()->{cursorX=x;cursorY=y;if(action==MotionEvent.ACTION_DOWN)hasPrevious=false;aim(action==MotionEvent.ACTION_DOWN);if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL)hasPrevious=false;});return true;}
}
